repo.harvests.py:
"""Harvest records."""


class Harvest:
    def __init__(self, field, kilos):
        self.field = field
        self.kilos = kilos

    def __repr__(self):
        return "Harvest(%r, %r)" % (self.field, self.kilos)


ROWS = [('upper', 33), ('lower', 27), ('hill', 34), ('upper', 41), ('river', 37), ('hill', 56), ('upper', 30)]


def load_harvests():
    """Yield the stored harvests one at a time."""
    for field, kilos in ROWS:
        yield Harvest(field, kilos)

repo.stock.py:
"""A pool of harvests with a remembered total."""


class HarvestPool:
    def __init__(self):
        self._harvests = []
        self._total = None

    def add(self, harvest):
        """Add one harvest to the pool."""
        self._harvests.append(harvest)
        self._total = None

    def remove(self, harvest):
        """Take one harvest out of the pool."""
        self._harvests.remove(harvest)

    def total(self):
        """Return the total kilos of the harvests in the pool."""
        if self._total is None:
            self._total = sum(x.kilos for x in self._harvests)
        return self._total


def group_by_field(harvests):
    """Return a dict from field to the list of harvests with that field."""
    groups = {}
    for x in harvests:
        groups.setdefault(x.field, []).append(x)
    return groups
